9	  items: Item[];
10	}
11	
12	interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	interface ClaimStep {
18	  op: "claim";
19	  policy: number;
20	  incident: { cause: string; damages: Damage[] };
21	}
22	
23	type Step = QuoteStep | ClaimStep;
