input.new_string:
const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);

// Each damaged item is reimbursed for its amount less one deductible, floored
// in MHPCO's favor.
const damagesPayout = (damages: Damage[]): number =>
  Math.floor(
    damages.reduce((sum, damage) => sum + (damage.amount - DEDUCTIBLE), 0),
  );

const claimResult = (claim: ClaimStep, policyItems: Item[]): ClaimResult => {
  const cap = CAP_MULTIPLIER * insuranceSum(policyItems);
  const payout = damagesPayout(claim.incident.damages);
  return { payout, remainingCap: cap - payout };
};
